INSERT INTO `objective_questions` (`id`, `exam_id`, `question_text`, `question_image`, `option_a`, `option_a_image`, `option_b`, `option_b_image`, `option_c`, `option_c_image`, `option_d`, `option_d_image`, `correct_option`, `mark`) VALUES (32,43,'What is the primary function of the respiratory system?',NULL,'To pump blood',NULL,'To exchange oxygen and carbon dioxide',NULL,'To digest food',NULL,'To filter waste from blood',NULL,'B',1),(33,43,'Which of the following is a normal adult heart rate (BPM)?',NULL,'40-60',NULL,'60-100',NULL,'110-130',NULL,'140-160',NULL,'B',1),(34,43,'Hypoglycemia refers to:',NULL,'High blood pressure',NULL,'Low blood sugar',NULL,'Low heart rate',NULL,'High body temperature',NULL,'B',1),(35,43,'The smallest unit of life in the human body is the:',NULL,'Tissue',NULL,'Organ',NULL,'Cell',NULL,'System',NULL,'C',0.5),(36,43,'Which vitamin is primarily obtained from sunlight?',NULL,'Vitamin A',NULL,'Vitamin B12',NULL,'Vitamin C',NULL,'Vitamin D',NULL,'D',0.5),(42,46,'What is the primary function of the respiratory system?',NULL,'To pump blood',NULL,'To exchange oxygen and carbon dioxide',NULL,'To digest food',NULL,'To filter waste from blood',NULL,'B',1),(43,46,'Which of the following is a normal adult heart rate (BPM)?',NULL,'40-60',NULL,'60-100',NULL,'110-130',NULL,'140-160',NULL,'B',1),(44,46,'Hypoglycemia refers to:',NULL,'High blood pressure',NULL,'Low blood sugar',NULL,'Low heart rate',NULL,'High body temperature',NULL,'B',1),(45,46,'The smallest unit of life in the human body is the:',NULL,'Tissue',NULL,'Organ',NULL,'Cell',NULL,'System',NULL,'C',0.5),(46,46,'Which vitamin is primarily obtained from sunlight?',NULL,'Vitamin A',NULL,'Vitamin B12',NULL,'Vitamin C',NULL,'Vitamin D',NULL,'D',0.5),(62,51,'What is the primary function of the respiratory system?',NULL,'To pump blood',NULL,'To exchange oxygen and carbon dioxide',NULL,'To digest food',NULL,'To filter waste from blood',NULL,'B',1),(63,51,'Which of the following is a normal adult hear